using System.ComponentModel.DataAnnotations;using MediStock.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;
namespace MediStock.Pages.Stock;
[Authorize]public sealed class CreateModel(MediStockDbContext db):PageModel{[BindProperty]public StockInput Input{get;set;}=new(){ExpiryDate=DateTime.UtcNow.AddMonths(12)};public IReadOnlyList<SelectListItem>Medicines{get;private set;}=[];public IReadOnlyList<SelectListItem>Suppliers{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>await Load(ct);public async Task<IActionResult>OnPostAsync(CancellationToken ct){if(Input.Quantity<0)ModelState.AddModelError("Input.Quantity","Quantity cannot be negative.");if(Input.ExpiryDate.Date<DateTime.UtcNow.Date)ModelState.AddModelError("Input.ExpiryDate","Expiry date cannot be in the past.");if(!await db.Medicines.AnyAsync(x=>x.Id==Input.MedicineId&&x.IsActive,ct)||!await db.Suppliers.AnyAsync(x=>x.Id==Input.SupplierId&&x.IsActive,ct))ModelState.AddModelError(string.Empty,"Select active medicine and supplier records.");if(await db.StockBatches.AnyAsync(x=>x.MedicineId==Input.MedicineId&&x.BatchNumber==Input.BatchNumber.Trim(),ct))ModelState.AddModelError("Input.BatchNumber","This medicine already has a batch with that number.");if(!ModelState.IsValid){await Load(ct);return Page();}db.StockBatches.Add(new StockBatch{MedicineId=Input.MedicineId,SupplierId=Input.SupplierId,BatchNumber=Input.BatchNumber.Trim(),Quantity=Input.Quantity,PurchasePrice=Input.PurchasePrice,ExpiryDate=Input.ExpiryDate,CreatedUtc=DateTime.UtcNow});await db.SaveChangesAsync(ct);TempData["StatusMessage"]="Stock batch added.";return RedirectToPage("Index");}private async Task Load(CancellationToken ct){Medicines=await db.Medicines.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(ct);Suppliers=await db.Suppliers.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new SelectListItem(x.Name,x.Id.ToString())).ToListAsync(ct);}}
public sealed class StockInput{[Required]public int MedicineId{get;set;}[Required]public int SupplierId{get;set;}[Required,StringLength(80)]public string BatchNumber{get;set;}="";[Range(0,100000000)]public int Quantity{get;set;}[Range(typeof(decimal),"0","999999999")]public decimal PurchasePrice{get;set;}[Required]public DateTime ExpiryDate{get;set;}=DateTime.UtcNow.AddMonths(12);}
